import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";var i=JSON.parse(`{"title":"What is audiobookshelf-mcp?","description":"","frontmatter":{},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md","lastUpdated":1788348313000}`),a={name:`guide/index.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="what-is-audiobookshelf-mcp" tabindex="-1">What is audiobookshelf-mcp? <a class="header-anchor" href="#what-is-audiobookshelf-mcp" aria-label="Permalink to “What is audiobookshelf-mcp?”">​</a></h1><p><a href="https://www.audiobookshelf.org/" target="_blank" rel="noreferrer">Audiobookshelf</a> is a self-hosted server for audiobooks and podcasts. It knows what you own, what you have listened to, how far you got and when — which is exactly the kind of thing you end up asking an assistant about, and exactly the kind of thing an assistant cannot answer without access to your library.</p><p><code>audiobookshelf-mcp</code> is a <a href="https://modelcontextprotocol.io" target="_blank" rel="noreferrer">Model Context Protocol</a> server that gives one to it. It exposes 44 tools over the Audiobookshelf REST API: 29 that read and 15 that write.</p><h2 id="what-you-can-do-with-it" tabindex="-1">What you can do with it <a class="header-anchor" href="#what-you-can-do-with-it" aria-label="Permalink to “What you can do with it”">​</a></h2><ul><li><strong>Ask about your library.</strong> &quot;Do I own anything by Frank Schätzing?&quot; &quot;Which of my audiobooks are longer than 20 hours?&quot; &quot;What&#39;s in the Ozean series and do I have all of it?&quot;</li><li><strong>Ask about your listening.</strong> &quot;What am I in the middle of?&quot; &quot;How much did I listen to last month?&quot; &quot;Which book did I abandon furthest in?&quot; &quot;What did I finish in 2025?&quot;</li><li><strong>Keep things tidy.</strong> Mark a book finished, jump the position to a chapter, drop a bookmark at the good bit, build a collection or a playlist from the answers to the questions above.</li></ul><h2 id="what-it-is-not" tabindex="-1">What it is not <a class="header-anchor" href="#what-it-is-not" aria-label="Permalink to “What it is not”">​</a></h2><p>It is not a player. There is no play, pause or seek: Audiobookshelf&#39;s playback session API is a state machine that belongs in a real client, and a model driving it would be a worse experience than the app you already have. <code>set_media_progress</code> moves your position; your phone does the playing.</p><p>It also deliberately stops well short of what an admin API key could do — see <a href="/guide/security">Security</a>.</p><h2 id="how-it-fits-together" tabindex="-1">How it fits together <a class="header-anchor" href="#how-it-fits-together" aria-label="Permalink to “How it fits together”">​</a></h2><p>The server speaks <strong>stdio</strong> and never listens on a port. Your MCP client starts it as a child process, it holds one Audiobookshelf API key, and it calls the REST API over HTTPS. There is no daemon to run and nothing to expose.</p><h2 id="the-response-size-problem" tabindex="-1">The response-size problem <a class="header-anchor" href="#the-response-size-problem" aria-label="Permalink to “The response-size problem”">​</a></h2><p>This is the part worth knowing before you start, because it shaped most of the design.</p><p>Audiobookshelf returns very large objects. A single expanded library item carries every audio file, every track and every chapter with full ffprobe metadata — one book easily exceeds 40 kB of JSON, and a page of 25 of them exceeds the useful context of any model. <code>/api/me/listening-stats</code> was measured at 95 kB on a three-year-old instance, because it embeds the totals of every calendar day since the account existed plus the complete media metadata of everything ever played.</p><p>So every tool that returns media answers with a <strong>compact projection</strong> by default: the fields that matter for browsing, ids and values matching Audiobookshelf&#39;s own names, descriptions truncated, embedded blobs dropped. <code>detail: &quot;full&quot;</code> gets you the raw object when you actually want it.</p><p>Three bounds sit under that, because the projection alone is not one: a <strong>5 MB ceiling</strong> on what is read from the instance, a <strong>100 000-byte ceiling</strong> on a tool result — applied in <code>jsonResult</code>, so <code>detail: &quot;full&quot;</code> is covered too, and it drops whole entries rather than characters — and a cap of <strong>25 embedded members</strong> in a compact collection or playlist, which report the real count alongside. <code>list_library_items</code> pages with <code>limit</code> and <code>page</code>; the other listing tools do not, because the Audiobookshelf routes behind them take no paging parameters and answer with everything at once.</p><p>The practical effect: <code>get_listening_stats</code> went from 95 kB to 3.5 kB, and <code>list_series</code> from 5.3 kB to 0.6 kB, without losing anything you would ask about.</p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to “Next”">​</a></h2><ul><li><a href="/guide/getting-started">Getting started</a> — API key, install, first call</li><li><a href="/guide/clients">Connecting clients</a> — Claude Code, Claude Desktop, Codex, Docker</li><li><a href="/reference/tools">Tools reference</a> — all 44, with every parameter</li></ul>`,18)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};